s=s.replace('本页是离线规划入口。布局框图使用示例数据；角色/环境原画、完整动画条与 G1 样稿尚未制作。没有修改游戏。HTML 不能替代原生 Godot UI，也不构成实机验收。','像素概念样稿已交付，等待你的方向与样稿审批。REAL 仅为历史实机对照；PROPOSED 均未接入游戏。人物动画与场景装饰仍需生产清稿。')
def section(id,html):
    global s
    s,n=re.subn(r'<section id="'+id+r'">.*?</section>',html,s,flags=re.S)
    assert n==1,id
